			written = { ["Back to the {area:380}"] = "Back to the Crossroads", ["Back to the {area:380}; the next guide starts here."] = "Back to the Crossroads; the next guide starts here.", ["Follow the road north to the {area:1703}; {npc:9316} stands just south of it."] = "Follow the road north to the Mor'shan Rampart; Wenikee stands just south of it.", ["Head east to the Venture Co. research site west of the {area:382}. Use the {object:4141}, close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471}."] = "Head east to the Venture Co. research site west of the Sludge Fen. Use the Control Console, close the three valves around the drill, use the console again, then take the Console Key from Tinkerer Sniggles.", ["Oasis Snapjaws crowd the water of {area:387}, south-west of the {area:380}."] = "Oasis Snapjaws crowd the water of Lushwater Oasis, south-west of the Crossroads.", ["On the way back to the {area:380}, the Razormane camp again: Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "On the way back to the Crossroads, the Razormane camp again: Geomancers and Defenders hold its eastern half; Kreenig Snarlsnout walks among them.", ["Plainstriders and Sunscale raptors roam the plains all around the {area:380}."] = "Plainstriders and Sunscale raptors roam the plains all around the Crossroads.", ["The Kolkar camps spread north-west of {npc:3389}; every Kolkar can drop {quest:855}. {area:386} lie in their middle, with Laden Mushrooms around the water. Savannah Prowlers roam the same plains."] = "The Kolkar camps spread north-west of Regthar; every Kolkar can drop Centaur Bracers. The Forgotten Pools lie in their middle, with Laden Mushrooms around the water. Savannah Prowlers roam the same plains.", ["The Tool Buckets sit around the Venture Co. camp in the {area:382}, east of {npc:9316}."] = "The Tool Buckets sit around the Venture Co. camp in the Sludge Fen, east of Wenikee.", ["The oasis lies south-east of the {area:380}. Test the seeds at the bubbling fissure in the middle of the water."] = "The oasis lies south-east of the Crossroads. Test the seeds at the bubbling fissure in the middle of the water.", ["Walk back up the road to the {area:380}. Savannah Prowlers hunt along it and on the plains west of town: finish the claws before you hand them in."] = "Walk back up the road to the Crossroads. Savannah Prowlers hunt along it and on the plains west of town: finish the claws before you hand them in.", ["Water Seekers, Thornweavers and Hunters hold the camp east of the {area:380}. The supply crates sit at its eastern end. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}. Kill Savannah Prowlers you pass for their claws."] = "Water Seekers, Thornweavers and Hunters hold the camp east of the Crossroads. The supply crates sit at its eastern end. Warriors: the Stolen Iron Chest stands in the camp. Shamans: the quilboar drop the Fire Tar. Kill Savannah Prowlers you pass for their claws.", ["You arrive from {area:379}. {npc:3338} stands by the inn; {npc:3429} and {npc:3449} on the tower platform; Helbrim and {npc:3464} by the north gate; {npc:3448} at the south gate."] = "You arrive from Far Watch Post. Sergra stands by the inn; Thork and Darsok on the tower platform; Helbrim and Gazrog by the north gate; Tonga at the south gate.", ["{area:386}"] = "The Forgotten Pools", ["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "Regthar stands at the Kolkar watch post just west of the Crossroads.", ["{npc:5878} camps beside the road east toward {area:392}."] = "Thun'grim camps beside the road east toward Ratchet.", ["{npc:5900} makes Fire Sapta from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Telf makes Fire Sapta from the tar and pouch. Use it by the brazier next to him to reveal the Minor Manifestation of Fire, kill it for the Glowing Ember, then place the ember in the brazier.", ["{npc:5900} waits on the {zone:1411} bank of the {area:814}, east of the Razormane camp."] = "Telf waits on the Durotar bank of the Southfury River, east of the Razormane camp.", ["{npc:5907} stands on the ridge north of the Razormane camp, east of the {area:380}."] = "Kranal Fiss stands on the ridge north of the Razormane camp, east of the Crossroads.", ["{quest:881}'s lair lies south of the {area:382}, north-east of the {area:380}. Use the horn {npc:3338} gave you there to call the white lion out. Then hearth to {area:392}."] = "Echeyakee's lair lies south of the Sludge Fen, north-east of the Crossroads. Use the horn Sergra gave you there to call the white lion out. Then hearth to Ratchet." },
